const trainingEvidenceAlreadyWovenIntoResearchStory = new Set([
  "dual-task",
  "multiple-object-tracking",
  "algebra-equation-solving",
  "phonological-decoding",
]);

function withTrainingEvidenceStory(paradigmId: string, sections: ParadigmStorySection[]) {
  const trainingEvidenceSection = trainingEvidenceStorySections[paradigmId];
  if (
    !trainingEvidenceSection ||
    trainingEvidenceAlreadyWovenIntoResearchStory.has(paradigmId) ||
    sections.some((section) => section.title === trainingEvidenceSection.title)
  ) {
    return sections;
  }
  const trainingLogicIndex = sections.findIndex((section) => section.title === "训练逻辑");
  if (trainingLogicIndex < 0) {
    return [...sections, trainingEvidenceSection];
  }
  return [
    ...sections.slice(0, trainingLogicIndex),
    trainingEvidenceSection,
    ...sections.slice(trainingLogicIndex),
  ];
}

