          "冲突效应的读法正好相反。两边箭头反向时，参与者通常比同向时更慢，两种条件相减，算出干扰让人多花了多少时间。这个数越大，时间代价越高。在最初的 40 名成人中，警觉和定向平均各省下约 50 毫秒，反向箭头平均多花 84 毫秒。三个差值彼此相关很低，提示方式又确实会改变干扰大小。它们可以分开观察，工作时仍会互相影响。",
          "2005 年，Fan 团队让 16 名成人在功能磁共振扫描中完成调整后的 ANT。提醒目标快来时，丘脑以及一些额顶区域出现了明显活动。位置线索更多牵动上顶叶和额叶眼动区。旁侧箭头制造冲突时，前扣带与多个额叶区域参与其中。每一种比较都会带出更广的脑活动，也会与其他比较发生重叠。Petersen 和 Posner 在 2012 年回顾这套框架时，又进一步细分了定向与执行控制网络。ANT 的分数因而更像几个观察窗口，无法直接当成三块脑区的体检结果。",
          "儿童训练研究把问题推向了发展与可塑性。Rueda、Posner 等人在 2005 年研究了 49 名 4 岁儿童和 24 名 6 岁儿童。训练组在 2 至 3 周内完成 5 次电脑练习，内容包括操纵小猫、预测小鸭位置、辨认人物和解决数量冲突。6 岁儿童还做了抑制反应游戏。儿童版 ANT 放在训练前后作测量，五条鱼取代箭头，孩子仍然只回答中间那条鱼朝哪边。部分对照组按同样次数到实验室观看儿童视频。",
