          "20 世纪 70 年代，视觉注意研究常用搜索任务：在一堆字母里找目标。Barbara Eriksen 和 Charles Eriksen 想把“找到目标”和“挡住旁边干扰”分开。1974 年，他们发表了一项非搜索实验，目标位置事先已经明确，参与者只需识别中央字母；目标两侧则放上与答案相容或不相容的噪声字母。",
          "实验规则很简单。字母被分成两组，每组对应一个按键。中央目标若属于第一组就按左键，属于第二组就按右键。两侧字母有时与中央目标属于同一反应组，等于一起推左键；有时属于另一组，中央目标要求左键，旁边字母却在推右键。参与者知道只看中间，眼睛也没有找错位置，反应仍会被不相容的旁侧字母拖慢。",
