          "后来，电脑屏幕取代了那排灯，实验也常改成字母匹配。先记住一个前提：屏幕每次只出现一个字母，旧字母随即消失。每来一个字母，参与者都要回答一次“匹配”或“不匹配”。0-back 通常只认一个事先规定的目标，比如见到 X 就按键，它主要检查人是否看清刺激、记住规则并正确反应。",
          "从 1-back 开始，判断对象会不断变化。看到 A → C → C，做 1-back 时，第三个 C 要按“匹配”，因为它和紧挨着的前一个字母相同。看到 A → C → A，做 2-back 时，第三个 A 要按“匹配”，因为往回数两轮也是 A。看到 A → C → B → A，做 3-back 时，第四个 A 才是匹配目标，因为它和三轮之前的 A 相同。N-back 不是让人最后背出整串字母，而是每出现一个新字母，都立刻找准 N 轮之前的那个，再完成一次比较。",
          "以 2-back 为例，新的字母出现后，刚才的“当前字母”会变成下一轮的“前一个”，原来的“前一个”又会变成“两轮之前”。人既要记住字母，也要记住它们各自在第几轮。只记得“刚才见过 A”还不够，必须知道那个 A 是一轮前还是两轮前。",
          "到了脑成像研究中，N-back 可以用同一套任务逐级增加负荷，还能把字母换成数字、图形或空间位置。2005 年，剑桥 MRC 认知与脑科学组的 Adrian Owen 等人汇总了 24 项 N-back 脑成像研究。结果显示，不同版本会稳定调动额叶和顶叶组成的工作记忆网络，具体材料和判断方式又会带来一些差别。N-back 因而不能被当成一个单独的“记忆仓库”测试，它同时需要保持顺序、按规则提取、比较和更新。",
          "2013 年，Kühn 等人把 46 名成人随机分组，一组大约完成 54 次数字更新和空间 N-back 训练，主动对照组也练习，但时间更短、难度固定。研究者在三个时间点进行脑成像，发现纹状体活动可能先升高、随后降低。一种解释是，学习早期需要更多调度，熟练后完成同样任务不再那么费力。无论脑区变亮还是变暗，都不能单独当作能力高低的刻度。",
          "儿童和学校研究已经有了一些直接证据。2005 年，赫尔辛基大学的 Eeva Aronen 等人让 55 名 6 至 13 岁儿童完成视觉和听觉 N-back，再把结果与教师对学业表现、注意和行为的评价进行比较。空间 N-back 表现较好的孩子，教师评价的在校学业表现也更好；表现较弱的孩子更常被报告有学习和注意方面的困难。这项研究说明两者有关联，但不能证明 N-back 表现较弱就是学业困难的原因。",
          "2020 年，Masha Jones、Susanne Jaeggi 等人进一步做了儿童训练研究。最终分析纳入 80 名 7 至 14 岁 ADHD 儿童，其中 41 人接受空间 N-back 训练，39 人接受知识与词汇主动对照；另有部分入组儿童因没有完成规定训练而未进入最终分析。约 5 周、20 次练习后，训练组在未训练过的 N-back 和抑制控制任务上出现了小幅改善，阅读理解、阅读流畅性和数学应用题却没有可靠的组间提升。两项研究回答的是不同问题：第一项说明 N-back 表现和在校学习状态有关，第二项说明练好 N-back 以后，阅读、数学和课堂表现不一定跟着改变。后面这些结果仍要单独测量。",
          "如果把范围放宽到多任务工作记忆训练，迁移的方向会更清楚。Jones 等人的另一项研究把 95 名 9 至 14 岁普通儿童随机分到 Cogmed、Cogmed 加元认知策略和自适应视觉搜索主动对照组。孩子在放学后训练 6 至 7 周，共 20 至 25 次。训练后，未练过的工作记忆任务有所提高，而且部分效果保持到三个月；数学推理只在训练刚结束时出现改善，三个月后没有保持，阅读理解从一开始就没有可靠提升。这项研究练的不是 N-back，因此不能拿来证明 N-back 有效，却能帮助我们看清工作记忆训练常见的迁移坡度：离训练形式越近，效果越容易出现；离真实学科越远，证据越弱。",
          "2016 年，Glenn Roberts 等人在 44 所学校先筛查 1723 名一年级儿童，再将其中 452 名低工作记忆儿童随机分组。训练组在学校完成 20 至 25 次 Cogmed，每次约 45 分钟。视空间短时记忆在 6 个月和 12 个月时仍能看到改善，到了 24 个月便不再明显；阅读、数学和拼写没有持续获益。N-back 训练、综合工作记忆训练和长期学校随访放在一起，给出的提醒很一致：练习可以先改变练过的操作和相似任务，但不能跳过迁移测量，直接把这种进步写成学业成绩提高。",
