          "错误本身会告诉我们该练什么。比如 2-back 出现 A → C → C，最后一个 C 和前一个相同，却和两轮之前的 A 不同，正确答案应是“不匹配”。如果孩子总在这里按键，说明他可能记住了字母，却取错了位置；如果前几轮还会做，后面开始乱猜，问题更可能出在持续更新或疲劳，而不是没有听懂规则。",
