          "规则可以很简单：听到高音说“高”，听到低音说“低”；同时看到一张脸，根据身份按左键或右键。耳朵和眼睛能够几乎同时收到信息，嘴和手也使用不同的输出器官，可一旦两项任务都需要把刺激翻译成正确反应，中间的选择阶段仍会排队。双任务成本并不等于感觉系统只能一次工作一个。",
          "实验里的排队常发生在几百毫秒内，课堂里的听讲、书写和找回位置却可能持续几秒。后者还会叠加工作记忆、笔记习惯和主动暂停等因素。因此，心理不应期只回答一个较窄的问题：两次反应选择怎样相互等待。它不能直接代表孩子整段课堂表现。",
          "2006 年，Paul Dux、Jason Ivanoff、Carlton Asplund 和 René Marois 用时间分辨 fMRI 追踪这个堵点。他们比较单任务与双任务的处理时序，结果把左侧后外侧前额叶和内侧额叶附近区域放到中央反应选择瓶颈的候选位置。证据支持某些中央步骤存在容量限制，却不意味着所有双任务都经过一条完全相同的固定线路。",
          "接下来的难题是：练熟以后，人看起来几乎能同时完成两项任务，瓶颈究竟消失了，还是只是排队变快？2009 年，Dux、Tombu、Harrison、Rogers、Tong 和 Marois 训练 7 名成人。每轮可能只做听觉口头反应、只做视觉按键，或者两个任务同时出现；参与者在 2 周内完成 8 至 12 次行为训练，并接受 3 次 fMRI。",
          "训练量很高，每次大约 90 分钟、540 个试次。两周后，双任务相对单任务的反应时成本从约 400 毫秒降到约 40 毫秒，只剩最初的十分之一左右，却没有完全消失。左侧额下沟附近的额下交界区对双任务的额外反应也随训练减小，分析更支持前额叶中的信息处理变快，而不是两条任务通道彻底分家。",
          "练习改善的是同一组脸、声音和反应映射。研究只有 7 名成人，没有独立训练对照，也没有测课堂听写、笔记或学业成绩。它证明高度相似的双任务经过大量练习后可以更快排队，不能证明人获得了通用的“同时做很多事”能力。",
          "孩子一边听一边写时，可以先看两项任务能否分段：理解新规则的几秒钟先停笔，意思稳定后再补关键词；若必须同时进行，没来得及处理的信息要有地方暂存。训练要减少切换和排队损失，无须把所有学习都设计成多任务挑战。",
