          "视觉和听觉刺激可以同时进入各自的感觉系统，早期识别也能在一定程度上并行。真正容易堵住的是把刺激按当前规则转换成反应的阶段：这张脸该按哪只手，这个声音该说哪个音节。前一项正在完成反应选择时，后一项的信息只能等待。",
