          "1997 年，美国爱荷华大学的 Steven Luck 和 Edward Vogel 设计了一组变化检测实验。参与者先看 1 到 12 个彩色方块，画面只出现 100 毫秒；空屏 900 毫秒后，第二个画面出现，任务是判断有没有一个方块变色。1 到 3 个物体时表现接近满分，从 4 个开始逐渐下降，成人在这组材料中的容量大约落在四个物体附近。",
