          "实验通常把过程压缩成一个个短试次。屏幕出现算式后，孩子不能用纸笔，要直接说出答案，或判断屏幕给出的等式是否正确。研究者同时记录答案、反应时间，有时还会追问孩子是直接想起、逐个计数还是拆分计算。题目从单个事实变成连续运算后，研究者才能继续判断：孩子缺的是事实、规则，还是中间结果的保持。",
          "2015 年，斯坦福大学 Vinod Menon 团队的 Teresa Iuculano 等人把这个问题带到数学学习困难儿童身上。过去的研究常把差异集中解释为顶叶数量加工异常，不同实验却有时看到活动偏高，有时又看到偏低。团队因此把问题改成：数字识别、数量关系、记忆和控制这些系统，能否在教学后重新协作？",
          "研究招募了 30 名 7 至 9 岁儿童，一半有数学学习困难，另一半是年龄、性别、总体认知、阅读和工作记忆都尽量匹配的典型发展儿童。训练前后，孩子都在扫描仪里判断加法等式是否正确；扫描仪外，他们还要在不用纸笔的情况下口头回答 24 道加法题。两组接受同一套辅导，研究者便能观察起点不同的儿童经过相同教学后，行为差距和脑活动差异怎样变化。研究没有设置完全不接受辅导的第三组，因此不能只凭这项实验排除重复测验或自然成长的影响。",
          "辅导持续 8 周，每周 3 次，每次约 40 至 50 分钟，共 22 课、约 15 至 20 小时。教师会讲数的意义、加减法关系和有效计数方法，也会帮助孩子逐渐直接取出已经学熟的算术事实。孩子练的是一整套基础数学策略，课程内容远多于反复做心算题。",
          "从论文图中的组平均看，数学学习困难组的加法判断正确率大约从 75% 提高到接近 87%，典型发展组约从 86% 提高到 90%，后者的变化没有达到研究设定的可靠标准。训练后，研究没有再检出两组正确率的可靠差异，但这不等于证明两组已经完全相同。速度变化也不一样：典型发展组反应变快，数学学习困难组没有检出可靠的提速。扫描仪外的口头加法中，训练前能检出的组间差异，训练后也不再可靠。",
          "脑成像呈现出相似的“差异缩小”：训练前两组在额叶、顶叶和腹侧视觉等多个区域的活动模式不同，训练后这些组间差异不再可靠。它说明行为改善伴随多套系统的活动变化，不能缩写成“某个脑区被练强了”。",
          "这项研究比较了两类儿童，却没有回答同样接受辅导的孩子为什么进步幅度不同。同一团队在另一项研究中，让 24 名数学能力水平不一、并非都属于数学学习困难的三年级儿童接受相同形式的 8 周辅导，并用 16 名没有接受辅导的同龄儿童排除重复测验和时间经过的影响。接受辅导的孩子答题更快、更准，也更常直接提取答案；未辅导组没有检出同样的可靠前后变化。",
          "研究还发现，在这批儿童中，训练开始前的海马结构及其与额叶等系统的连接，与后来谁进步更多有关。这里的“预测”发生在训练之前，不表示辅导把海马结构改大了，也不能拿一批人的共同趋势给单个孩子判定潜力。两项研究样本都不大，训练又是综合数学辅导；结果支持基础加法策略、速度和事实提取可以随教学改善。两项研究都没有直接测量多步心算中间结果的保持，其他数学内容与长期成绩也要单独测量。",
