          "难度可以沿四条线逐步增加：数字变大、步骤增加、呈现时间缩短、外部提示减少。一次只推一条。先允许写下中间结果，再只保留一个提示框，最后尝试完全心算；如果撤掉草稿后错误突然增加，就退回上一层，而不是要求孩子硬撑。",
          "反馈按错误类型记录：事实错误、运算顺序错误、中间结果丢失、旧数字干扰和答案输出错误。常见问题是只盯最后答案，孩子即使碰巧答对，也可能靠反复重算完成；真正的进步应包括重算次数减少，并能复述当前结果和下一步。",
          "儿童研究中的完整数学辅导采用 8 周、每周 3 次、每次 40 至 50 分钟，总量约 15 至 20 小时，但其中包含概念教学、策略和事实练习，不能当作纯心算处方。日常支持可先用每次 10 至 15 分钟、每周 3 至 4 次、连续 6 至 8 周作为观察起点，并保留正常书面计算学习。",
