          "2003 年，Elise Temple、John Gabrieli 等人在斯坦福开展了一项儿童研究。他们面对的难题是：阅读障碍儿童在音韵任务中常见的左侧颞顶系统反应差异，经过训练后能不能改变，还是会一直保持原样？",
          "20 名 8 至 12 岁阅读障碍儿童在训练前后进入扫描仪，另有 12 名正常阅读儿童间隔约 8 周重复扫描。扫描任务很巧妙：看到 T（tee）和 D（dee）时，两个字母名称押韵，应按键；看到 G（gee）和 K（kay）时不押韵，不按。研究者再用“两个字母是否完全相同”和“线条方向是否相同”作对照，把看字母、按键和音韵比较尽量分开。",
          "阅读障碍组接受 8 周电脑化训练，每天 100 分钟、每周 5 天，平均完成 27.9 天。七类练习同时覆盖声音辨别、音素识别、相近词区分、听指令、语法和听力理解。训练后，真实词阅读、假词解码和篇章理解测验都有提高，若干语言相关区域的任务活动也发生变化。可是扫描中的字母押韵正确率本身没有可靠提高，研究也缺少未训练的阅读障碍对照组；训练又包含很多成分，所以不能把所有变化单独归功于音韵解码。",
          "Temple 的结果把希望和限制同时摆在桌面上：声音辨别、音素操作和语言理解可以一起教，部分阅读表现与任务脑反应也可能随学习改变；可是多种训练成分缠在一起，哪一部分起了多大作用仍不清楚。研究只针对阅读障碍儿童，而且强度很高，不能把这套剂量当作普通儿童的通用方案，更不能用一次押韵或拆音表现给孩子诊断。",
