          "自己做数学题时，课本说“2 是方程 x + 3 = 5 的根”。这里的“根”不能沿用植物的地下部分，也不是平方根符号；前面的“方程”和后面的等式把当前意义限定为“代入后使等式成立的数”。孩子确认语境后，要压住最熟悉的日常词义，把新的学科义项接到已有的“解方程”概念上。",
          "语义加工稳的孩子能说清一个概念属于哪一类、与相近概念哪里相同又哪里不同，并能根据上下文切换多义词；不稳时，他常背得出定义的前半句，却不会用例子验证，也会把熟悉词义硬套进新的学科语境。读过的词不少，知识仍像一堆没有连线的卡片。",
