          "词义看起来最像“存在脑中的知识”，研究起来却格外棘手。让人判断“猫是不是动物”，结果里既有看字、按键，也有分类和常识；让人静静休息，脑中又可能自己想起人物、计划和往事。到 21 世纪初，语义脑成像论文已经超过 500 篇，各研究指出的区域却很不一致。研究者首先得回答：怎样才算真正把语义加工从其他活动中比较出来？",
          "美国威斯康星医学院的神经学家 Jeffrey Binder 与 Rutvik Desai、William Graves、Lisa Conant 决定把这团材料重新清理。2009 年，他们逐篇审查 520 篇论文，只有 120 篇符合严格条件；最终整理 187 个语义对照、1642 名参与者和 1145 个激活点。工作量大，真正困难的却不是统计，而是为每个实验判断对照条件是否公平。",
          "语义任务并不只有一种。参与者可能判断“麻雀是不是生物”，比较“医生和护士是否相关”，核对“香蕉是不是黄色”，或判断一句话合不合理。对照材料必须尽量匹配字形、声音、反应和难度；若用安静休息作对照，休息时自发出现的意义和回忆反而可能把真实语义活动减掉。Binder 团队因此把任务设计本身也纳入解释。",
          "元分析显示，语义加工依靠分布式网络：左侧中颞、下颞和腹侧颞叶保存或接入不同概念属性，角回与邻近下顶叶整合关系和语境，左额下回在多个意义竞争时帮助检索与选择，内侧额叶、后扣带和楔前叶等区域提供更广的情境与记忆背景。没有一个小点可以装下“意义”。",
